import unittest
import copy, json, sys
sys.path.insert(0, '.')

import importlib, os, tempfile
MOD = "hivetools.helpers"
FILES = {'notes.txt': 'first note\n\n  second note  \nthird\n', 'empty.txt': ''}

def run_case(case):
    mod = importlib.import_module(MOD)
    with tempfile.TemporaryDirectory() as tmp:
        for name, text in FILES.items():
            with open(os.path.join(tmp, name), "w") as fh:
                fh.write(text)
        args = [a.replace("@tmp", tmp) if isinstance(a, str) else a for a in case[1]]
        res = getattr(mod, case[0])(*args)
        if case[0].startswith("append_"):
            with open(args[0]) as fh:
                res = fh.read()
        return res

def _norm(x):
    return json.loads(json.dumps(x))

def _outcome(case):
    try:
        return _norm(run_case(copy.deepcopy(case)))
    except Exception as e:
        return {"raises": type(e).__name__}

CASES = json.loads("[[\"hive_log_path\", [\"/srv/data\", \"jan\"]], [\"hive_log_path\", [\"/srv/data\", \"audit\"]], [\"hive_archive_name\", [\"notes.md\"]], [\"hive_archive_name\", [\"notes.md\"]], [\"hive_archive_name\", [\"logs/jan.txt\"]], [\"hive_kind\", [1]], [\"hive_kind\", [2.5]], [\"hive_kind\", [\"x\"]], [\"hive_kind\", [[1]]], [\"hive_kind\", [null]], [\"hive_kind\", [{\"a\": 1}]], [\"hive_pick\", [null, null]], [\"hive_pick\", [0, null]], [\"hive_pick\", [null, \"x\"]], [\"hive_pick\", [\"\", 3]], [\"hive_state\", [[]]], [\"hive_state\", [[0]]], [\"hive_state\", [[0, 0]]], [\"hive_state\", [[0, 0, 0]]], [\"hive_state\", [[0, 0, 0, 0, 0, 0, 0]]]]")
WANT = json.loads("[\"/srv/data/logs/jan.txt\", \"/srv/data/logs/audit.txt\", \"archive/notes.old.md\", \"archive/notes.old.md\", \"logs/archive/jan.old.txt\", \"number\", \"number\", \"text\", \"sequence\", \"other\", \"other\", \"none\", 0, \"x\", \"\", \"empty\", \"few\", \"few\", \"many\", \"many\"]")


class RecordedTests(unittest.TestCase):
    def test_recorded_outcomes(self):
        for i, case in enumerate(CASES):
            with self.subTest(i=i, case=str(case)[:200]):
                self.assertEqual(_outcome(case), WANT[i])


if __name__ == '__main__':
    unittest.main()

