"""Small helpers for the apiary."""
from pathlib import Path


def hive_log_path(base, name):
    return str(Path(base) / "logs" / f"{name}.txt")


def hive_archive_name(path):
    p = Path(path)
    return str(p.parent / "archive" / f"{p.stem}.old{p.suffix}")


def hive_kind(value):
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "text"
    if isinstance(value, (list, tuple)):
        return "sequence"
    return "other"


def hive_pick(first, second):
    if first is not None:
        return first
    if second is None:
        return "none"
    return second


def hive_state(items):
    if not items:
        return "empty"
    if len(items) < 3:
        return "few"
    return "many"

