"""Small helpers for the apiary."""
import os


def hive_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def hive_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def hive_kind(value):
    if type(value) == int or type(value) == float:
        return "number"
    if type(value) == str:
        return "text"
    if type(value) == list or type(value) == tuple:
        return "sequence"
    return "other"


def hive_pick(first, second):
    if first != None:
        return first
    if second == None:
        return "none"
    return second


def hive_state(items):
    if len(items) == 0:
        return "empty"
    if len(items) > 0 and len(items) < 3:
        return "few"
    return "many"

