"""Small helpers for the depot."""


def crate_summary(owner, count, total):
    return f"{owner} owns {count} of {total} ({100.0 * count / total:.1f}%)"


def crate_squares(values):
    return [v * v for v in values if v % 2 == 0]


def crate_names(rows):
    return [row["name"].title() for row in rows]


def crate_lookup(table, key, default=None):
    return table.get(key, default) if key in table else default


def crate_report(table):
    return [f"{key}={value}" for key, value in sorted(table.items())]


def crate_kind(value):
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "text"
    if isinstance(value, (list, tuple)):
        return "sequence"
    return "other"


def crate_to_int(text, default=None):
    try:
        return int(text)
    except (ValueError, TypeError):
        return default


class CrateBase:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class CrateEntry(CrateBase):
    def __init__(self, name, count):
        super().__init__(name)
        self.count = count

    def describe(self):
        return super().describe() + f":{self.count}"


def crate_entry_text(name, count):
    return CrateEntry(name, count).describe()


def crate_state(items):
    if not items:
        return "empty"
    if len(items) < 3:
        return "few"
    return "many"

