"""Small helpers for the depot."""


def crate_summary(owner, count, total):
    return "{} owns {} of {} ({:.1f}%)".format(owner, count, total, 100.0 * count / total)


def crate_squares(values):
    out = []
    for v in values:
        if v % 2 == 0:
            out.append(v * v)
    return out


def crate_names(rows):
    names = []
    for row in rows:
        names.append(row["name"].title())
    return names


def crate_lookup(table, key, default=None):
    if key in table.keys():
        return table[key]
    return default


def crate_report(table):
    lines = []
    for key in sorted(table.keys()):
        lines.append("%s=%s" % (key, table[key]))
    return lines


def crate_kind(value):
    if type(value) == int or type(value) == float:
        return "number"
    if type(value) == str:
        return "text"
    if type(value) == list or type(value) == tuple:
        return "sequence"
    return "other"


def crate_to_int(text, default=None):
    try:
        return int(text)
    except:
        return default


class CrateBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class CrateEntry(CrateBase):
    def __init__(self, name, count):
        super(CrateEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(CrateEntry, self).describe() + ":%d" % self.count


def crate_entry_text(name, count):
    return CrateEntry(name, count).describe()


def crate_state(items):
    if len(items) == 0:
        return "empty"
    if len(items) > 0 and len(items) < 3:
        return "few"
    return "many"

