"""Small helpers for the allotment."""
from pathlib import Path


def read_plot_notes(path):
    with open(path) as f:
        text = f.read()
    return [ln.strip() for ln in text.splitlines() if ln.strip()]


def append_plot_note(path, note):
    with open(path, "a") as f:
        f.write(note + "\n")


def plot_log_path(base, name):
    return str(Path(base) / "logs" / f"{name}.txt")


def plot_archive_name(path):
    p = Path(path)
    return str(p.parent / "archive" / f"{p.stem}.old{p.suffix}")


def plot_dot(weights, values):
    return sum(w * v for w, v in zip(weights, values))


def plot_marked(items):
    return [f"{i}.{item}" for i, item in enumerate(items, 1)]


def plot_pick(first, second):
    if first is not None:
        return first
    if second is None:
        return "none"
    return second


def plot_to_int(text, default=None):
    try:
        return int(text)
    except (ValueError, TypeError):
        return default


class PlotBase:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class PlotEntry(PlotBase):
    def __init__(self, name, count):
        super().__init__(name)
        self.count = count

    def describe(self):
        return super().describe() + f":{self.count}"


def plot_entry_text(name, count):
    return PlotEntry(name, count).describe()


def plot_state(items):
    if not items:
        return "empty"
    if len(items) < 3:
        return "few"
    return "many"

