"""Small helpers for the allotment."""
import os


def read_plot_notes(path):
    f = open(path)
    text = f.read()
    f.close()
    return [ln.strip() for ln in text.splitlines() if ln.strip()]


def append_plot_note(path, note):
    f = open(path, "a")
    f.write(note + "\n")
    f.close()


def plot_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def plot_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def plot_dot(weights, values):
    total = 0
    for i in range(len(weights)):
        total += weights[i] * values[i]
    return total


def plot_marked(items):
    out = []
    for i in range(len(items)):
        out.append("%d.%s" % (i + 1, items[i]))
    return out


def plot_pick(first, second):
    if first != None:
        return first
    if second == None:
        return "none"
    return second


def plot_to_int(text, default=None):
    try:
        return int(text)
    except:
        return default


class PlotBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class PlotEntry(PlotBase):
    def __init__(self, name, count):
        super(PlotEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(PlotEntry, self).describe() + ":%d" % self.count


def plot_entry_text(name, count):
    return PlotEntry(name, count).describe()


def plot_state(items):
    if len(items) == 0:
        return "empty"
    if len(items) > 0 and len(items) < 3:
        return "few"
    return "many"

