"""Small helpers for the marina."""


def berth_summary(owner, count, total):
    return f"{owner} owns {count} of {total} ({100.0 * count / total:.1f}%)"


def berth_double(x):
    return x * 2


def berth_clamp(x, lo, hi):
    return max(lo, min(hi, x))


def berth_state(items):
    if not items:
        return "empty"
    if len(items) < 3:
        return "few"
    return "many"

