"""Small helpers for the stockroom."""
from pathlib import Path


def shelf_label(name, qty, unit):
    return f"{name}: {qty} {unit}"


def shelf_log_path(base, name):
    return str(Path(base) / "logs" / f"{name}.txt")


def shelf_archive_name(path):
    p = Path(path)
    return str(p.parent / "archive" / f"{p.stem}.old{p.suffix}")


def shelf_squares(values):
    return [v * v for v in values if v % 2 == 0]


def shelf_names(rows):
    return [row["name"].title() for row in rows]


def shelf_lookup(table, key, default=None):
    return table.get(key, default) if key in table else default


def shelf_report(table):
    return [f"{key}={value}" for key, value in sorted(table.items())]


def shelf_dot(weights, values):
    return sum(w * v for w, v in zip(weights, values))


def shelf_marked(items):
    return [f"{i}.{item}" for i, item in enumerate(items, 1)]


def shelf_pick(first, second):
    if first is not None:
        return first
    if second is None:
        return "none"
    return second


def shelf_to_int(text, default=None):
    try:
        return int(text)
    except (ValueError, TypeError):
        return default


class ShelfBase:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class ShelfEntry(ShelfBase):
    def __init__(self, name, count):
        super().__init__(name)
        self.count = count

    def describe(self):
        return super().describe() + f":{self.count}"


def shelf_entry_text(name, count):
    return ShelfEntry(name, count).describe()

