"""Small helpers for the stockroom."""
import os


def shelf_label(name, qty, unit):
    return "%s: %d %s" % (name, qty, unit)


def shelf_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def shelf_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def shelf_squares(values):
    out = []
    for v in values:
        if v % 2 == 0:
            out.append(v * v)
    return out


def shelf_names(rows):
    names = []
    for row in rows:
        names.append(row["name"].title())
    return names


def shelf_lookup(table, key, default=None):
    if key in table.keys():
        return table[key]
    return default


def shelf_report(table):
    lines = []
    for key in sorted(table.keys()):
        lines.append("%s=%s" % (key, table[key]))
    return lines


def shelf_dot(weights, values):
    total = 0
    for i in range(len(weights)):
        total += weights[i] * values[i]
    return total


def shelf_marked(items):
    out = []
    for i in range(len(items)):
        out.append("%d.%s" % (i + 1, items[i]))
    return out


def shelf_pick(first, second):
    if first != None:
        return first
    if second == None:
        return "none"
    return second


def shelf_to_int(text, default=None):
    try:
        return int(text)
    except:
        return default


class ShelfBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class ShelfEntry(ShelfBase):
    def __init__(self, name, count):
        super(ShelfEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(ShelfEntry, self).describe() + ":%d" % self.count


def shelf_entry_text(name, count):
    return ShelfEntry(name, count).describe()

