"""Small helpers for the greenhouse."""
from pathlib import Path


def sensor_label(name, qty, unit):
    return f"{name}: {qty} {unit}"


def sensor_log_path(base, name):
    return str(Path(base) / "logs" / f"{name}.txt")


def sensor_archive_name(path):
    p = Path(path)
    return str(p.parent / "archive" / f"{p.stem}.old{p.suffix}")


def sensor_kind(value):
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "text"
    if isinstance(value, (list, tuple)):
        return "sequence"
    return "other"


def sensor_double(x):
    return x * 2


def sensor_clamp(x, lo, hi):
    return max(lo, min(hi, x))


def sensor_to_int(text, default=None):
    try:
        return int(text)
    except (ValueError, TypeError):
        return default


class SensorBase:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class SensorEntry(SensorBase):
    def __init__(self, name, count):
        super().__init__(name)
        self.count = count

    def describe(self):
        return super().describe() + f":{self.count}"


def sensor_entry_text(name, count):
    return SensorEntry(name, count).describe()


def sensor_state(items):
    if not items:
        return "empty"
    if len(items) < 3:
        return "few"
    return "many"

