"""Small helpers for the greenhouse."""
import os


def sensor_label(name, qty, unit):
    return "%s: %d %s" % (name, qty, unit)


def sensor_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def sensor_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def sensor_kind(value):
    if type(value) == int or type(value) == float:
        return "number"
    if type(value) == str:
        return "text"
    if type(value) == list or type(value) == tuple:
        return "sequence"
    return "other"


sensor_double = lambda x: x * 2
sensor_clamp = lambda x, lo, hi: max(lo, min(hi, x))


def sensor_to_int(text, default=None):
    try:
        return int(text)
    except:
        return default


class SensorBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class SensorEntry(SensorBase):
    def __init__(self, name, count):
        super(SensorEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(SensorEntry, self).describe() + ":%d" % self.count


def sensor_entry_text(name, count):
    return SensorEntry(name, count).describe()


def sensor_state(items):
    if len(items) == 0:
        return "empty"
    if len(items) > 0 and len(items) < 3:
        return "few"
    return "many"

