import importlib, os, tempfile
MOD = "sensortools.helpers"
FILES = {'notes.txt': 'first note\n\n  second note  \nthird\n', 'empty.txt': ''}

def run_case(case):
    mod = importlib.import_module(MOD)
    with tempfile.TemporaryDirectory() as tmp:
        for name, text in FILES.items():
            with open(os.path.join(tmp, name), "w") as fh:
                fh.write(text)
        args = [a.replace("@tmp", tmp) if isinstance(a, str) else a for a in case[1]]
        res = getattr(mod, case[0])(*args)
        if case[0].startswith("append_"):
            with open(args[0]) as fh:
                res = fh.read()
        return res

def norm(x):
    return json.loads(json.dumps(x))


class HelperTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("[\"sensor_label\", [\"north\", 86, \"pcs\"]]")
        self.assertEqual(norm(run_case(case)), json.loads("\"north: 86 pcs\""))

    def test_example_2(self):
        case = json.loads("[\"sensor_kind\", [1]]")
        self.assertEqual(norm(run_case(case)), json.loads("\"number\""))

    def test_example_3(self):
        case = json.loads("[\"sensor_clamp\", [-14, 0, 40]]")
        self.assertEqual(norm(run_case(case)), json.loads("0"))

    def test_example_4(self):
        case = json.loads("[\"sensor_to_int\", [null, null]]")
        self.assertEqual(norm(run_case(case)), json.loads("null"))


if __name__ == '__main__':
    unittest.main()

