def read_loom_notes(path):
    with open(path) as f:
        text = f.read()
    return [ln.strip() for ln in text.splitlines() if ln.strip()]


def append_loom_note(path, note):
    with open(path, "a") as f:
        f.write(note + "\n")


def loom_kind(value):
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "text"
    if isinstance(value, (list, tuple)):
        return "sequence"
    return "other"


def loom_dot(weights, values):
    return sum(w * v for w, v in zip(weights, values))


def loom_marked(items):
    return [f"{i}.{item}" for i, item in enumerate(items, 1)]


class LoomBase:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class LoomEntry(LoomBase):
    def __init__(self, name, count):
        super().__init__(name)
        self.count = count

    def describe(self):
        return super().describe() + f":{self.count}"


def loom_entry_text(name, count):
    return LoomEntry(name, count).describe()

