"""Small helpers for the weaving mill."""


def read_loom_notes(path):
    f = open(path)
    text = f.read()
    f.close()
    return [ln.strip() for ln in text.splitlines() if ln.strip()]


def append_loom_note(path, note):
    f = open(path, "a")
    f.write(note + "\n")
    f.close()


def loom_kind(value):
    if type(value) == int or type(value) == float:
        return "number"
    if type(value) == str:
        return "text"
    if type(value) == list or type(value) == tuple:
        return "sequence"
    return "other"


def loom_dot(weights, values):
    total = 0
    for i in range(len(weights)):
        total += weights[i] * values[i]
    return total


def loom_marked(items):
    out = []
    for i in range(len(items)):
        out.append("%d.%s" % (i + 1, items[i]))
    return out


class LoomBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class LoomEntry(LoomBase):
    def __init__(self, name, count):
        super(LoomEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(LoomEntry, self).describe() + ":%d" % self.count


def loom_entry_text(name, count):
    return LoomEntry(name, count).describe()

