CASES = json.loads("[[\"kiln_summary\", [\"ana\", 1, 12]], [\"kiln_summary\", [\"ana\", 6, 49]], [\"kiln_summary\", [\"ana\", 7, 30]], [\"kiln_summary\", [\"x\", 1, 0]], [\"kiln_log_path\", [\"/var/lib/x\", \"q3\"]], [\"kiln_log_path\", [\"/srv/data\", \"audit\"]], [\"kiln_archive_name\", [\"/srv/logs/q3.csv\"]], [\"kiln_archive_name\", [\"notes.md\"]], [\"kiln_archive_name\", [\"notes.md\"]], [\"kiln_squares\", [[11, 8, 19, 14, 11, 2, 16]]], [\"kiln_squares\", [[14, 16, 11]]], [\"kiln_squares\", [[11, 6, 3, 6, 18]]], [\"kiln_names\", [[{\"name\": \"bo\"}, {\"name\": \"bo\"}, {\"name\": \"ada lovelace\"}]]], [\"kiln_names\", [[{\"name\": \"bo\"}, {\"name\": \"ada lovelace\"}]]], [\"kiln_kind\", [1]], [\"kiln_kind\", [2.5]], [\"kiln_kind\", [\"x\"]], [\"kiln_kind\", [[1]]], [\"kiln_kind\", [null]], [\"kiln_kind\", [{\"a\": 1}]], [\"kiln_dot\", [[], []]], [\"kiln_dot\", [[4, 2], [8, 8]]], [\"kiln_dot\", [[2, 2, 3, 2], [5, 4, 7, 2]]], [\"kiln_marked\", [[\"a\"]]], [\"kiln_marked\", [[\"a\", \"b\", \"c\"]]], [\"kiln_double\", [2]], [\"kiln_double\", [44]], [\"kiln_clamp\", [35, 0, 40]], [\"kiln_clamp\", [29, 0, 40]], [\"kiln_clamp\", [40, 0, 40]], [\"kiln_entry_text\", [\"a\", 12]], [\"kiln_entry_text\", [\"bee\", 26]], [\"kiln_entry_text\", [\"a\", 5]], [\"kiln_state\", [[]]], [\"kiln_state\", [[0]]], [\"kiln_state\", [[0, 0]]], [\"kiln_state\", [[0, 0, 0]]], [\"kiln_state\", [[0, 0, 0, 0, 0, 0, 0]]]]")
WANT = json.loads("[\"ana owns 1 of 12 (8.3%)\", \"ana owns 6 of 49 (12.2%)\", \"ana owns 7 of 30 (23.3%)\", {\"raises\": \"ZeroDivisionError\"}, \"/var/lib/x/logs/q3.txt\", \"/srv/data/logs/audit.txt\", \"/srv/logs/archive/q3.old.csv\", \"archive/notes.old.md\", \"archive/notes.old.md\", [64, 196, 4, 256], [196, 256], [36, 36, 324], [\"Bo\", \"Bo\", \"Ada Lovelace\"], [\"Bo\", \"Ada Lovelace\"], \"number\", \"number\", \"text\", \"sequence\", \"other\", \"other\", 0, 48, 43, [\"1.a\"], [\"1.a\", \"2.b\", \"3.c\"], 4, 88, 35, 29, 40, \"base:a:12\", \"base:bee:26\", \"base:a:5\", \"empty\", \"few\", \"few\", \"many\", \"many\"]")


class RecordedTests(unittest.TestCase):
    def test_recorded_outcomes(self):
        for i, case in enumerate(CASES):
            with self.subTest(i=i, case=str(case)[:200]):
                self.assertEqual(_outcome(case), WANT[i])


