"""Small helpers for the pottery."""
import os


def kiln_summary(owner, count, total):
    return "{} owns {} of {} ({:.1f}%)".format(owner, count, total, 100.0 * count / total)


def kiln_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def kiln_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def kiln_squares(values):
    out = []
    for v in values:
        if v % 2 == 0:
            out.append(v * v)
    return out


def kiln_names(rows):
    names = []
    for row in rows:
        names.append(row["name"].title())
    return names


def kiln_kind(value):
    if type(value) == int or type(value) == float:
        return "number"
    if type(value) == str:
        return "text"
    if type(value) == list or type(value) == tuple:
        return "sequence"
    return "other"


def kiln_dot(weights, values):
    total = 0
    for i in range(len(weights)):
        total += weights[i] * values[i]
    return total


def kiln_marked(items):
    out = []
    for i in range(len(items)):
        out.append("%d.%s" % (i + 1, items[i]))
    return out


kiln_double = lambda x: x * 2
kiln_clamp = lambda x, lo, hi: max(lo, min(hi, x))


class KilnBase(object):
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "base:" + self.name


class KilnEntry(KilnBase):
    def __init__(self, name, count):
        super(KilnEntry, self).__init__(name)
        self.count = count

    def describe(self):
        return super(KilnEntry, self).describe() + ":%d" % self.count


def kiln_entry_text(name, count):
    return KilnEntry(name, count).describe()


def kiln_state(items):
    if len(items) == 0:
        return "empty"
    if len(items) > 0 and len(items) < 3:
        return "few"
    return "many"

