WANT = json.loads("[1, null, null, [\"b=2\", \"m=3\", \"x=1\"], [], \"number\", \"number\", \"text\", \"sequence\", \"other\", \"other\", 0, 18, 52, [], [\"1.a\", \"2.b\", \"3.c\"], 2, 86, 40, 40, 39, 12, null, -1, 7, null, null, \"base:a:21\", \"base:a:9\", \"base:a:15\", \"empty\", \"few\", \"few\", \"many\", \"many\", [\"first note\", \"second note\", \"third\"], [], {\"raises\": \"FileNotFoundError\"}, \"hello\\n\", \"first note\\n\\n  second note  \\nthird\\nfourth\\n\"]")


