"""Small helpers for the weaving mill."""
import os


def loom_log_path(base, name):
    return os.path.join(base, "logs", name + ".txt")


def loom_archive_name(path):
    stem, ext = os.path.splitext(os.path.basename(path))
    return os.path.join(os.path.dirname(path), "archive", stem + ".old" + ext)


def loom_squares(values):
    out = []
    for v in values:
        if v % 2 == 0:
            out.append(v * v)
    return out


def loom_names(rows):
    names = []
    for row in rows:
        names.append(row["name"].title())
    return names


def loom_lookup(table, key, default=None):
    if key in table.keys():
        return table[key]
    return default


def loom_report(table):
    lines = []
    for key in sorted(table.keys()):
        lines.append("%s=%s" % (key, table[key]))
    return lines


def loom_dot(weights, values):
    total = 0
    for i in range(len(weights)):
        total += weights[i] * values[i]
    return total


def loom_marked(items):
    out = []
    for i in range(len(items)):
        out.append("%d.%s" % (i + 1, items[i]))
    return out

